import json, sys
d=json.load(open('openapi.json'))
comps=d['components']['schemas']
def resolve(ref):
    return comps[ref.split('/')[-1]]
def fields(schema, depth=0):
    if '$ref' in schema:
        schema=resolve(schema['$ref'])
    out=[]
    props=schema.get('properties',{})
    req=set(schema.get('required',[]))
    for name,p in props.items():
        t=p.get('type') or ('ref:'+p['$ref'].split('/')[-1] if '$ref' in p else '')
        if 'anyOf' in p:
            t='|'.join([(x.get('type') or ('ref:'+x['$ref'].split('/')[-1] if '$ref' in x else x.get('type','null'))) for x in p['anyOf']])
        if 'allOf' in p:
            t='ref:'+p['allOf'][0]['$ref'].split('/')[-1]
        if t=='array':
            it=p.get('items',{})
            t='array<'+(it.get('type') or (it.get('$ref','').split('/')[-1]))+'>'
        star='*' if name in req else ' '
        enum=p.get('enum')
        default=p.get('default','')
        extra=(' enum='+str(enum) if enum else '')+(' def='+str(default) if default!='' else '')
        out.append(f"    {star}{name}: {t}{extra}")
    return '\n'.join(out)

for path in sys.argv[1:]:
    for method in ('post','put','patch'):
        if path in d['paths'] and method in d['paths'][path]:
            op=d['paths'][path][method]
            rb=op.get('requestBody')
            print(f"### {method.upper()} {path}")
            if rb:
                sch=rb['content']['application/json']['schema']
                print(fields(sch))
            print()
